export function sceneParams(input={}){if(!input||typeof input!=='object'||Array.isArray(input))throw Error('Invalid scene parameters.');const p={...SCENE_DEFAULTS,...input};for(const [k,v]of Object.entries(input)){if(SCENE_FIELDS[k]){const[,a,b]=SCENE_FIELDS[k];if(!Number.isFinite(v)||v<a||v>b)throw Error('Invalid scene parameter: '+k);}else if(k==='protectPeople'){if(typeof v!=='boolean')throw Error('Invalid people protection.');}else if(k==='shadowMode'){if(!['contact','floating','cast'].includes(v))throw Error('Invalid shadow mode.');}else throw Error('Unknown scene parameter.');}return p;}
export function presetScene(id,analysis,current={}){const preset=SCENE_PRESETS.find(p=>p.id===id);if(!preset)throw Error('Unknown scene preset.');const p={...SCENE_DEFAULTS,...preset.params,amount:current.amount??100};if(id==='auto'&&analysis){p.exposure=Math.round(Math.max(-.6,Math.min(1.25,Math.log2(.43/Math.max(.06,analysis.median))*.65))*20)/20;p.shadows=Math.round(Math.min(60,15+analysis.darkFraction*45));}if(p.celestial&&analysis?.orbCenter){p.orbX=Math.round(analysis.orbCenter[0]*100);p.orbY=Math.round(analysis.orbCenter[1]*100);}return sceneParams(p);}
export const SCENE_ACTIONS=[{id:'studio',name:'Studio tự động',steps:['auto','soft']},{id:'catalog',name:'Sản phẩm có bóng mềm',steps:['product','contact']},{id:'autumn-leaves',name:'Thu vàng · lá bay',steps:['autumn','falling-leaves']},{id:'snow',name:'Đông lạnh · tuyết rơi',steps:['winter']},{id:'night-city',name:'Đêm · trăng · đèn',steps:['night']},{id:'bright-day',name:'Ngày sáng · trời trong',steps:['day']}];
export function actionScene(action,analysis,current={}){if(!action||typeof action.name!=='string'||action.name.length>80||!Array.isArray(action.steps)||!action.steps.length||action.steps.length>16)throw Error('Invalid action.');let p={...SCENE_DEFAULTS,...current};for(const id of action.steps){if(id==='falling-leaves')Object.assign(p,{leaves:30,leafSize:5,motion:50,wind:32,depth:65});else{const preset=SCENE_PRESETS.find(v=>v.id===id);if(!preset)throw Error('Unknown action step.');Object.assign(p,id==='auto'?presetScene(id,analysis,p):preset.params);}}if(p.celestial&&analysis?.orbCenter){p.orbX=Math.round(analysis.orbCenter[0]*100);p.orbY=Math.round(analysis.orbCenter[1]*100);}return sceneParams(p);}
export function validateStyleFile(value){if(!value||value.format!=='luma-styles'||value.version!==1||!Array.isArray(value.presets)||value.presets.length>50||!Array.isArray(value.actions)||value.actions.length>50)throw Error('Tệp preset/actions không hợp lệ.');for(const p of value.presets){if(typeof p.name!=='string'||!p.name.trim()||p.name.length>80)throw Error('Invalid preset name.');sceneParams(p.params);}for(const a of value.actions)actionScene(a);return value;}
